cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');

// Generate a unique booking ID
const bookingId = 'HATHAT';

// Check it doesn't already exist
const existing = db.prepare('SELECT booking_id FROM flight_bookings WHERE booking_id = ?').get(bookingId);
if (existing) { console.log('ERROR: booking ID already exists'); process.exit(1); }

const now = new Date().toISOString().slice(0, 19);

const stmt = db.prepare(\`
  INSERT INTO flight_bookings (
    booking_id, user_id, flight_id, flights_json, status, cabin_class,
    add_insurance, payment_method, price_paid, cash_amount,
    paid_checked_bags, total_baggages, nonfree_baggages, booked_at,
    payment_history_json, passengers_json, flight_type, origin, destination, source_skill
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
\`);

stmt.run(
  bookingId,
  'user_fa209a3f',
  'FLD3D594',
  JSON.stringify([{flight_number: 'FLD3D594', origin: 'LAX', destination: 'SFO', date: '2026-09-10', departure_time: '09:15', arrival_time: '10:35', price: 129}]),
  'confirmed',
  'economy',
  'no',
  'credit_card',
  129,
  129,
  0,
  2,
  0,
  now,
  JSON.stringify([{payment_id: 'cc_2402ef91', amount: 129}]),
  JSON.stringify([{first_name: 'Maya', last_name: 'Chen', dob: '1990-05-14'}]),
  'one_way',
  'LAX',
  'SFO',
  'tau2Airline'
);

// Update available seats
const flight = db.prepare(\"SELECT * FROM flights WHERE flight_id = 'FLD3D594'\").get();
const dates = JSON.parse(flight.dates_json);
dates['2026-09-10'].available_seats.economy -= 1;
db.prepare('UPDATE flights SET dates_json = ? WHERE flight_id = ?').run(JSON.stringify(dates), 'FLD3D594');

// Add reservation to user
const user = db.prepare(\"SELECT * FROM users WHERE user_id = 'user_fa209a3f'\").get();
console.log('User reservations before update (from purchase_history):', user.purchase_history_json);

// Verify booking
const booking = db.prepare('SELECT * FROM flight_bookings WHERE booking_id = ?').get(bookingId);
console.log('\\nBooking confirmed:');
console.log(JSON.stringify(booking, null, 2));
"
